package in.kabadiwala.connect.controller; import in.kabadiwala.connect.dto.ApiResponse; import in.kabadiwala.connect.service.PaymentService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.Map; @RestController @RequestMapping("/api/v1/recycler/payments") @PreAuthorize("hasRole('RECYCLER')") public class PaymentController {private final PaymentService s;public PaymentController(PaymentService s){this.s=s;} @PostMapping("/transactions/{tx}/initiate") ApiResponse<?> init(Authentication a,@PathVariable String tx){return ApiResponse.ok("Payment initiated",s.initiate(a.getName(),tx));} @PostMapping("/{id}/confirm") ApiResponse<?> confirm(Authentication a,@PathVariable String id,@RequestBody Map<String,Object> b){return ApiResponse.ok("Payment verified",s.confirm(a.getName(),id,(String)b.getOrDefault("providerPaymentId",""),(String)b.getOrDefault("signature",""),Boolean.TRUE.equals(b.get("manualConfirmed"))));}}
